"use client"

import type { StandardSchemaV1 } from "@standard-schema/spec"
import { useEffect, useId, useLayoutEffect, useRef, useState, type ComponentType, type ReactNode } from "react"
import type { FieldValues, Path, UseFormReturn } from "react-hook-form"

import { Button } from "@/components/ui/button"
import {
  Form,
  FormActions,
  FormRootError,
  toFormErrors,
  useFormInstance,
  type FormProps,
  type FormValuesOf,
} from "@/components/ui/form"
import { useFormContext } from "@/components/ui/form-context"
import { StepFormProgress } from "@/components/ui/step-form-progress"
import { cn } from "@/lib/utils"

type FormStep<Values extends FieldValues = FieldValues> = {
  /** Stable id, reported by `onStepChange` and accepted by `step` and `defaultStep`. */
  id: string
  title: ReactNode
  description?: ReactNode
  /** The step's fields, usually `FormField`s; the form instance is there for `watch`-free logic like `getValues`. */
  render: (form: UseFormReturn<Values>) => ReactNode
  /** The fields Next validates; the step's mounted `FormField`s by default. */
  fields?: Path<Values>[]
  /**
   * Runs once the step's fields are valid, before moving on. Return nothing to continue, or an error in any shape
   * `onSubmit` may throw (`{ fieldErrors, message }`, a string, a `FormServerError`) to stay.
   */
  validate?: (values: Values) => unknown
}

type StepDirection = "next" | "back" | "error"

type StepChangeDetails = {
  index: number
  /** The step it leaves. */
  previous: string
  /** `error` when a failed submit returns to the step that holds the first invalid field. */
  direction: StepDirection
}

type StepFormLabels = {
  next?: ReactNode
  back?: ReactNode
  submit?: ReactNode
  /** Names the progress list for screen readers. */
  progress?: string
}

type StepFormProps<Schema extends StandardSchemaV1> = Omit<FormProps<Schema>, "children"> & {
  steps: FormStep<FormValuesOf<Schema>>[]
  /** The current step's id, controlled. */
  step?: string
  defaultStep?: string
  onStepChange?: (step: string, details: StepChangeDetails) => void
  /** Button and progress labels in the page's language; English by default. */
  labels?: StepFormLabels
  /** What screen readers hear once a submit or a step's `validate` has been pending for a second. */
  pendingLabel?: string
  headingLevel?: 2 | 3 | 4
  rootErrorTitle?: ReactNode
}

type StepFormFrameProps<Schema extends StandardSchemaV1> = StepFormProps<Schema> & {
  cancel?: ReactNode
  onCancel?: () => void
  body?: ComponentType<{ children?: ReactNode }>
  actionsClassName?: string
}

/** A new object for every move, so moving to the same direction twice still runs the focus effect. */
type StepMove = { direction: StepDirection }

function errorPaths(errors: Record<string, unknown>, prefix = ""): string[] {
  return Object.entries(errors).flatMap(([key, value]) => {
    if (!value || typeof value !== "object") return []
    const path = prefix ? `${prefix}.${key}` : key
    return "type" in value || "message" in value ? [path] : errorPaths(value as Record<string, unknown>, path)
  })
}

const related = (a: string, b: string) => a === b || a.startsWith(`${b}.`) || b.startsWith(`${a}.`)

function DefaultBody({ children }: { children?: ReactNode }) {
  return <div className="flex min-w-0 flex-col gap-group">{children}</div>
}

type ContentProps = {
  steps: FormStep[]
  index: number
  move: StepMove | null
  go: (target: number, direction: StepDirection) => void
  labels?: StepFormLabels
  pendingLabel?: string
  headingLevel: 2 | 3 | 4
  rootErrorTitle?: ReactNode
  cancel?: ReactNode
  onCancel?: () => void
  Body: ComponentType<{ children?: ReactNode }>
  actionsClassName?: string
}

function StepFormContent({
  steps,
  index,
  move,
  go,
  labels,
  pendingLabel,
  headingLevel,
  rootErrorTitle,
  cancel,
  onCancel,
  Body,
  actionsClassName,
}: ContentProps) {
  const form = useFormInstance()
  const context = useFormContext("StepForm")
  const step = steps[index]!
  const last = index === steps.length - 1
  const headingId = useId()
  const heading = useRef<HTMLHeadingElement>(null)
  const seen = useRef(new Map<string, string[]>())
  const [validating, setValidating] = useState(false)
  const Heading = `h${headingLevel}` as const

  useEffect(() => {
    seen.current.set(step.id, [...context.fields.keys()])
  })
  useEffect(() => {
    if (move?.direction === "next" || move?.direction === "back") heading.current?.focus()
  }, [move])

  const stepOf = (paths: string[]) => {
    const found = steps.findIndex((candidate) => {
      const names = candidate.fields ?? seen.current.get(candidate.id) ?? []
      return paths.some((path) => names.some((name) => related(path, name)))
    })
    if (found >= 0) return found
    // A step never shown (after `defaultStep`) and without `fields` is the only place the field can be.
    const unknown = steps.findIndex((candidate) => !candidate.fields && !seen.current.has(candidate.id))
    return unknown < 0 ? index : unknown
  }

  const next = async () => {
    form.clearErrors("root")
    const names = step.fields ?? [...context.fields.keys()]
    setValidating(true)
    try {
      if (names.length > 0 && !(await form.trigger(names))) return context.requestFocus()
      const problem = await step.validate?.(form.getValues())
      if (problem !== undefined && problem !== null) {
        context.applyError(problem)
        return context.requestFocus()
      }
      go(index + 1, "next")
    } finally {
      setValidating(false)
    }
  }

  const { setInterceptor } = context
  useLayoutEffect(() => {
    setInterceptor({
      beforeSubmit: async () => {
        if (last) return true
        await next()
        return false
      },
      onInvalid: (errors) => go(stepOf(errorPaths(errors)), "error"),
      onError: (error) => go(stepOf(Object.keys(toFormErrors(error)?.fieldErrors ?? {})), "error"),
    })
  })
  useLayoutEffect(() => () => setInterceptor(null), [setInterceptor])

  return (
    <>
      <StepFormProgress steps={steps} current={index} label={labels?.progress ?? "Progress"} />
      <Body>
        <section aria-labelledby={headingId} data-slot="step-form-step" className="flex min-w-0 flex-col gap-group">
          <div className="flex flex-col gap-inline">
            <Heading
              ref={heading}
              id={headingId}
              tabIndex={-1}
              data-slot="step-form-title"
              className="text-title-sm tracking-tight outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              {step.title}
            </Heading>
            {step.description === undefined ? null : (
              <p className="text-body-sm text-muted-foreground">{step.description}</p>
            )}
          </div>
          {step.render(form)}
        </section>
        <FormRootError title={rootErrorTitle} />
      </Body>
      <FormActions
        submitLabel={last ? (labels?.submit ?? "Submit") : (labels?.next ?? "Next")}
        pendingLabel={pendingLabel}
        pending={validating}
        cancel={cancel}
        onCancel={onCancel}
        secondaryAction={
          index === 0 ? null : (
            <Button
              type="button"
              variant="ghost"
              disabled={context.pending || validating}
              onClick={() => go(index - 1, "back")}
            >
              {labels?.back ?? "Back"}
            </Button>
          )
        }
        className={actionsClassName}
      />
    </>
  )
}

function StepFormFrame<Schema extends StandardSchemaV1>({
  steps,
  step: stepProp,
  defaultStep,
  onStepChange,
  labels,
  pendingLabel,
  headingLevel = 2,
  rootErrorTitle,
  cancel,
  onCancel,
  body = DefaultBody,
  actionsClassName,
  className,
  ...form
}: StepFormFrameProps<Schema>) {
  const [ownStep, setOwnStep] = useState(() => defaultStep ?? steps[0]?.id)
  const [move, setMove] = useState<StepMove | null>(null)
  const current = stepProp ?? ownStep
  const index = Math.max(
    0,
    steps.findIndex((candidate) => candidate.id === current),
  )

  const go = (target: number, direction: StepDirection) => {
    const destination = steps[target]
    if (!destination || target === index) return
    setMove({ direction })
    if (stepProp === undefined) setOwnStep(destination.id)
    onStepChange?.(destination.id, { index: target, previous: steps[index]!.id, direction })
  }

  return (
    <Form {...form} className={cn("min-w-0", className)}>
      <StepFormContent
        steps={steps as FormStep[]}
        index={index}
        move={move}
        go={go}
        labels={labels}
        pendingLabel={pendingLabel}
        headingLevel={headingLevel}
        rootErrorTitle={rootErrorTitle}
        cancel={cancel}
        onCancel={onCancel}
        Body={body}
        actionsClassName={actionsClassName}
      />
    </Form>
  )
}

/**
 * A multi-step form: one schema, one step's fields at a time. Next (or Enter) validates only that step, Back keeps
 * every value, and the last step submits everything through `onSubmit`, with the same error mapping as `Form`.
 */
function StepForm<Schema extends StandardSchemaV1>(props: StepFormProps<Schema>) {
  return <StepFormFrame {...props} />
}

export { StepForm, StepFormFrame }
export type { FormStep, StepChangeDetails, StepDirection, StepFormLabels, StepFormProps }

import type { ReactNode } from "react"
import { CheckIcon } from "lucide-react"

import { cn } from "@/lib/utils"

type StepState = "complete" | "current" | "upcoming"

const markerClassName: Record<StepState, string> = {
  complete: "border-primary bg-primary text-primary-foreground",
  current: "border-primary bg-background text-foreground ring-2 ring-ring",
  upcoming: "border-input-strong bg-background text-muted-foreground",
}

const titleClassName: Record<StepState, string> = {
  complete: "text-muted-foreground",
  current: "font-medium text-foreground",
  upcoming: "text-muted-foreground narrow:sr-only",
}

type StepFormProgressProps = {
  steps: { id: string; title: ReactNode }[]
  current: number
  /** Names the list for screen readers, in the page's language. */
  label: string
  className?: string
}

/** Where the wizard is: an ordered list, the current step marked with `aria-current="step"`. */
function StepFormProgress({ steps, current, label, className }: StepFormProgressProps) {
  return (
    <ol
      aria-label={label}
      data-slot="step-form-progress"
      className={cn("flex min-w-0 flex-wrap items-center gap-items text-body-sm", className)}
    >
      {steps.map((step, index) => {
        const state: StepState = index < current ? "complete" : index === current ? "current" : "upcoming"
        return (
          <li
            key={step.id}
            data-state={state}
            aria-current={state === "current" ? "step" : undefined}
            className="flex min-w-0 items-center gap-inline"
          >
            {index === 0 ? null : <span aria-hidden="true" className="h-px w-4 shrink-0 bg-border" />}
            <span
              aria-hidden="true"
              className={cn(
                "flex size-6 shrink-0 items-center justify-center rounded-full border font-mono text-caption",
                markerClassName[state],
              )}
            >
              {state === "complete" ? <CheckIcon strokeWidth={2.5} className="size-3.5" /> : index + 1}
            </span>
            <span className={cn("truncate", titleClassName[state])}>{step.title}</span>
          </li>
        )
      })}
    </ol>
  )
}

export { StepFormProgress }
export type { StepFormProgressProps }

"use client"

import type { StandardSchemaV1 } from "@standard-schema/spec"
import type { VariantProps } from "class-variance-authority"
import { useState, type ComponentProps, type ReactNode } from "react"

import type { buttonVariants } from "@/components/ui/button"
import {
  Dialog,
  DialogBackdrop,
  DialogBody,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  type DialogSize,
} from "@/components/ui/dialog"
import {
  StepFormFrame,
  type StepFormLabels,
  type StepFormProps,
  StepForm,
  type FormStep,
  type StepChangeDetails,
  type StepDirection,
} from "@/components/ui/step-form"
import { cn } from "@/lib/utils"

type StepDialogLabels = StepFormLabels & {
  /** The button that closes the dialog; "Cancel" by default. */
  cancel?: ReactNode
}

type StepDialogProps<Schema extends StandardSchemaV1> = Omit<
  StepFormProps<Schema>,
  "labels" | "headingLevel" | "onPendingChange" | "className"
> & {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Content of the button that opens the dialog. Omit it when opening through `open`. */
  trigger?: ReactNode
  triggerVariant?: VariantProps<typeof buttonVariants>["variant"]
  title: ReactNode
  description?: ReactNode
  size?: DialogSize
  labels?: StepDialogLabels
  /** Where focus goes once the dialog closes; the trigger by default. */
  returnFocus?: ComponentProps<typeof DialogContent>["finalFocus"]
  className?: string
}

/**
 * A StepForm in a Dialog: the progress and actions stay in view while the step scrolls, Escape, outside presses and
 * Cancel do nothing while submitting, and it closes once `onSubmit` resolves. It starts from the first step each time
 * it opens.
 */
function StepDialog<Schema extends StandardSchemaV1>({
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  trigger,
  triggerVariant,
  title,
  description,
  size = "md",
  labels,
  returnFocus,
  onSubmit,
  className,
  ...stepForm
}: StepDialogProps<Schema>) {
  const [ownOpen, setOwnOpen] = useState(defaultOpen)
  const [pending, setPending] = useState(false)
  const open = openProp ?? ownOpen

  const setOpen = (next: boolean) => {
    if (openProp === undefined) setOwnOpen(next)
    onOpenChange?.(next)
  }

  const submit: StepFormProps<Schema>["onSubmit"] = async (values, helpers) => {
    await onSubmit(values, helpers)
    setOpen(false)
  }

  return (
    <Dialog
      open={open}
      onOpenChange={(next, details) => {
        if (!next && pending) details.cancel()
        else setOpen(next)
      }}
      dismissible={!pending}
    >
      {trigger === undefined ? null : <DialogTrigger variant={triggerVariant}>{trigger}</DialogTrigger>}
      <DialogBackdrop />
      <DialogContent
        size={size}
        finalFocus={returnFocus}
        aria-busy={pending || undefined}
        className={cn("overflow-hidden", className)}
      >
        <DialogHeader>
          <DialogTitle>{title}</DialogTitle>
          {description === undefined ? null : <DialogDescription>{description}</DialogDescription>}
        </DialogHeader>
        <StepFormFrame
          {...stepForm}
          onSubmit={submit}
          onPendingChange={setPending}
          labels={labels}
          headingLevel={3}
          cancel={labels?.cancel ?? "Cancel"}
          onCancel={() => {
            if (!pending) setOpen(false)
          }}
          body={DialogBody}
          actionsClassName="shrink-0"
          className="min-h-0 flex-1"
        />
      </DialogContent>
    </Dialog>
  )
}

export { StepDialog }
export { StepForm }
export type { FormStep, StepChangeDetails, StepDirection, StepFormLabels, StepFormProps }
export type { StepDialogLabels, StepDialogProps }
